  const subbarVisible   = screen !== 'success';
  const subbarActiveIdx = SCREEN_TO_SUBBAR[screen] ?? -1;
  const fabVisible      = screen === 'home';
  const sendVisible     = screen === 'home' && !!selectedTenant;
  const conveyorDir     = conveyor?.dir || 'up';

  const batchAutoProps = {
    go, tenants, invoices, onBatchSend: handleBatch, sending: batchMutation.isPending,
    schedules, onPauseResume: handlePauseResume, onCancel: handleCancelSchedule,
    busyId: busyScheduleId, reminderSettings, onUpdateReminders: (patch: any) => reminderMutation.mutate(patch),
  };

  const renderScreen = (id: string) => {
    if (id === 'home')     return <RequestsHome invoices={invoices} tenants={tenants} outstanding={outstanding} outstandingExpenses={outstandingExpenses} go={go} onRowTap={handleRowTap}
      filter={stackFilter} onFilter={setStackFilter} remindMode={remindMode}
      onRemind={(id: string) => resendOneMutation.mutate(id)}
      remindBusyId={resendOneMutation.isPending ? (resendOneMutation.variables as string) : null} />;
    if (id === 'tenants')  return <ChooseTenant tenants={tenants} invoices={invoices} go={go} onSelect={handleTenantSelect} splitMode={splitMode} onToggleSplit={() => setSplitMode(m => !m)} />;
    if (id === 'amount')   return <RentAmount go={go} selectedTenant={selectedTenant} backTo={amountDest} onCommit={(c: number) => { setAmount(c); go(amountDest); }} />;
    if (id === 'send')     return <SendRentLink go={go} selectedTenant={selectedTenant} amount={amount} onSend={handleSend} sending={sendMutation.isPending} frequency={frequency} setFrequency={setFrequency} splitMode={splitMode} onEditAmount={() => { setAmountDest('send'); go('amount'); }} />;
    if (id === 'bill')     return <ChargeBill go={go} selectedTenant={selectedTenant} amount={amount} onEditAmount={() => { setAmountDest('bill'); go('amount'); }} chargeType={chargeType} setChargeType={setChargeType} label={chargeLabel} setLabel={setChargeLabel} dueSel={dueSel} setDueSel={setDueSel} splitOn={splitMode} onToggleSplit={() => setSplitMode(m => !m)} onSend={handleBill} sending={billMutation.isPending} docUrl={chargeDocUrl} docName={chargeDocName} uploadingDoc={uploadingDoc} onUploadDoc={uploadChargeDoc} onClearDoc={clearChargeDoc} />;
    if (id === 'external') return <MarkExternal go={go} selectedTenant={selectedTenant} amount={amount} invoices={invoices} onMark={handleMark} marking={markMutation.isPending} />;
    if (id === 'batch')    return <BatchAndAutoScreen {...batchAutoProps} />;
    if (id === 'success')  return <SentSuccess amount={amount} label={successLabel} go={go} kind={successKind} />;
    return null;
  };

  return (
    <div className="tp-viewport" ref={viewportRef}>
      <style>{TP_TERM_CSS}</style>

      {conveyor && (
        <div key={'leave-' + conveyor.prevId} className={`tp-layer leaving ${conveyorDir}`}>
          {renderScreen(conveyor.prevId)}
        </div>
      )}
      <div key={'enter-' + currentId + '-' + contentKey} className={`tp-layer${conveyor ? ' entering ' + conveyorDir : ''}`}>
        {renderScreen(currentId)}
      </div>

      <div className="tp-overlay">
        <TopBanner msg={banner} />

        <div className={`tp-pfab${fabVisible ? ' show' : ' hide'}`}>
          <FabBtn onClick={() => go('tenants')} />
        </div>

        {/* Full-width row: split pill pinned far-left, action bar centred in the
            space to its right, send pinned right. They are flex siblings, so they
            can never overlap regardless of how wide the bar gets. */}
        <div
          className={`tp-psubbar${subbarVisible ? ' show' : ' hide'}${isFeatureScreen ? ' feature' : ''}`}
          style={isFeatureScreen ? { transform: `translateY(calc(${boundaryDelta}px - 100% - 20px))` } : undefined}
        >
          <div className={`tp-split-slot${screen === 'tenants' ? ' show' : ''}`}>
            <SplitPill on={splitMode} onToggle={() => setSplitMode(m => !m)} />
          </div>
          <div className="tp-subbar-center">
            <SubBar activeIdx={subbarActiveIdx} onPick={handleSubbarPick} compact={sendVisible} hideLabel={false} />
          </div>
          <div className={`tp-send-slot${sendVisible ? ' show' : ''}`}>
            <SendBtn onClick={handleSend} />
          </div>
        </div>
      </div>

      <div className={`tp-toast${toastMsg ? ' show' : ''}`}>{toastMsg}</div>

      {rowAction && (
        <InvoiceActionSheet
          invoice={rowAction}
          busy={voidMutation.isPending || resendOneMutation.isPending || markMutation.isPending}
          onClose={() => setRowAction(null)}
          onEditResend={openEditResend}
          onResend={() => { resendOneMutation.mutate(rowAction.id); setRowAction(null); }}
          onMarkReceived={() => { markMutation.mutate({ invoiceId: rowAction.id, ref: '' }); setRowAction(null); }}
          onVoid={handleVoid}
        />
      )}
    </div>
  );
}

